package com.ecommerce.product; import com.ecommerce.common.ApiException; import com.ecommerce.user.User; import com.ecommerce.user.UserRepository; import org.springframework.security.core.Authentication; import jakarta.validation.constraints.NotBlank; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/categories") public class CategoryController {record Req(@NotBlank String name,UUID parentId){} private final CategoryRepository repo; private final UserRepository users; public CategoryController(CategoryRepository r,UserRepository u){repo=r;users=u;} @GetMapping List<Category> all(){return repo.findAll();} @PostMapping Category create(@RequestBody @jakarta.validation.Valid Req r,Authentication a){User u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();if(u.getRole()!=User.Role.ADMIN&&u.getRole()!=User.Role.SELLER)throw new ApiException("Seller or admin role required");Category c=new Category();c.setName(r.name());if(r.parentId()!=null)c.setParent(repo.findById(r.parentId()).orElseThrow(()->new ApiException("Parent category not found")));return repo.save(c);}}
